void SerializeToString(const VkDescriptorDataEXT& value, std::stringstream& stream) {
    stream << "VkDescriptorDataEXT{";
    if (value.pSampler) {
        stream << "{[";
        SerializeToString(*value.pSampler, stream);
        stream << "], 1}";
    }
    else {
        SerializeToString(nullptr, stream);
    }
    stream << ", ";
    if (value.pCombinedImageSampler) {
        stream << "{[";
        SerializeToString(*value.pCombinedImageSampler, stream);
        stream << "], 1}";
    }
    else {
        SerializeToString(nullptr, stream);
    }
    stream << ", ";
    if (value.pInputAttachmentImage) {
        stream << "{[";
        SerializeToString(*value.pInputAttachmentImage, stream);
        stream << "], 1}";
    }
    else {
        SerializeToString(nullptr, stream);
    }
    stream << ", ";
    if (value.pSampledImage) {
        stream << "{[";
        SerializeToString(*value.pSampledImage, stream);
        stream << "], 1}";
    }
    else {
        SerializeToString(nullptr, stream);
    }
    stream << ", ";
    if (value.pStorageImage) {
        stream << "{[";
        SerializeToString(*value.pStorageImage, stream);
        stream << "], 1}";
    }
    else {
        SerializeToString(nullptr, stream);
    }
    stream << ", ";
    if (value.pUniformTexelBuffer) {
        stream << "{[";
        SerializeToString(*value.pUniformTexelBuffer, stream);
        stream << "], 1}";
    }
    else {
        SerializeToString(nullptr, stream);
    }
    stream << ", ";
    if (value.pStorageTexelBuffer) {
        stream << "{[";
        SerializeToString(*value.pStorageTexelBuffer, stream);
        stream << "], 1}";
    }
    else {
        SerializeToString(nullptr, stream);
    }
    stream << ", ";
    if (value.pUniformBuffer) {
        stream << "{[";
        SerializeToString(*value.pUniformBuffer, stream);
        stream << "], 1}";
    }
    else {
        SerializeToString(nullptr, stream);
    }
    stream << ", ";
    if (value.pStorageBuffer) {
        stream << "{[";
        SerializeToString(*value.pStorageBuffer, stream);
        stream << "], 1}";
    }
    else {
        SerializeToString(nullptr, stream);
    }
    stream << ", ";
    SerializeToString(value.accelerationStructure, stream);
    stream << "}";
}

